var t=`0206-gambas-al-ajillo`;var a=`world-0206`;var n=`ES`;var s=`southern-europe`;var o=4;var r=11;var l={en:`Gambas al Ajillo`,ua:`Креветки з часником`};var d={en:`A traditional Spain dish made with garlic, shrimp, parsley, lemon juice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: часник, креветка, петрушка, лимонний сік. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 3 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 3 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:3,i:[[`extra-virgin-olive-oil`,75,`ml`],[`garlic`,6,`clove`],[`crushed-red-pepper`,3,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 6 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 6 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:6,i:[[`shrimp`,600,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,18,`g`],[`lemon-juice`,20,`ml`],[`table-salt`,null,`to_taste`]]}];var m={slug:t,id:a,country:`ES`,region:s,servings:4,minutes:11,title:l,text:d,steps:u};export{n as country,m as default,a as id,r as minutes,s as region,o as servings,t as slug,u as steps,d as text,l as title};